import React, { useState } from "react";

export function TooltipHint() {
  const [visible, setVisible] = useState(false);
  return (
    <div className="relative inline-block">
      <button onMouseEnter={() => setVisible(true)} onMouseLeave={() => setVisible(false)} onFocus={() => setVisible(true)} onBlur={() => setVisible(false)} className="px-3 py-1.5 rounded-[8px] border border-border bg-card text-xs text-foreground hover:bg-muted">Hover over me</button>
      {visible && (
        <div role="tooltip" className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 px-2.5 py-1 bg-neutral-900 text-white dark:bg-neutral-100 dark:text-neutral-900 text-[11px] font-medium rounded shadow-md whitespace-nowrap z-30 pointer-events-none">
          Quick helpful tip
          <div className="absolute top-full left-1/2 -translate-x-1/2 border-4 border-transparent border-t-neutral-900 dark:border-t-neutral-100" />
        </div>
      )}
    </div>
  );
}
